SELECT s.id, s.user_id, u.nickname, u.avatar, s.content, s.images, s.like_count, s.view_count, s.comment_count, s.create_time FROM story s LEFT JOIN `user` u ON s.user_id = u.id
s.deleted = 0 AND s.user_id = #{userId} AND s.status = 1
ORDER BY s.create_time DESC LIMIT #{offset}, #{limit}
